1	import { useState } from 'react';
2	import { Link } from '@tanstack/react-router';
3	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
4	import { getJson, postJson } from '../../api/http';
5	import { asString, useSearchParam } from '../../url/useSearchParam';
6	import { InvoicesToolbar } from '../../slots/defs/invoicesToolbar';
7	import { InvoiceRowCells } from '../../slots/defs/invoiceRowCells';
8	import { money } from '../../ui/money';
9	import { invoiceStatus } from '../../ui/invoiceStatus';
10	
11	// An invoice as the server returns it: which project it belongs to, its amount, and its lifecycle
12	// status (DRAFT until sent, SENT until paid, then PAID).
13	export type Invoice = {
14	  id: number;
15	  projectId: number;
16	  amount: number;
17	  status: string;
18	  issuedDate: string;
19	  dueDate: string;
20	  // How much is still owed after payments (amount minus every payment recorded against it), derived
21	  // and sent by the server. The amount-due cell (features/invoices/dueAmount.slot.tsx) reads this.
22	  amountDue: number;
23	};
24	
25	// A project's invoices: the list scoped to this project, their derived total, and the form to add a
26	// new one. Server data is read with useQuery under the ['invoices'] key and changed with
27	// useMutation + invalidateQueries — never copied into state, never hand-maintained. The only
28	// useState is the amount the user is currently typing (rule 4).
29	export function InvoicesPanel({ projectId }: { projectId: number }) {
30	  const queryClient = useQueryClient();
31	  // The sort lives in the URL (owned by features/invoices/sortByDue.slot.tsx). The panel reads the
32	  // same key and asks the server for the ordered list, so it stays a single source of truth — no
33	  // server data copied into state or re-sorted by hand. The key still starts with 'invoices', so
34	  // writes that invalidateQueries({ queryKey: ['invoices'] }) still refresh it.
35	  const [sort] = useSearchParam('invoiceSort', asString);
36	  const invoices = useQuery({
37	    queryKey: ['invoices', sort],
38	    queryFn: () =>
39	      getJson<Invoice[]>(
40	        sort ? `/api/invoices?sort=${encodeURIComponent(sort)}` : '/api/invoices',
41	      ),
42	  });
43	
44	  const [amount, setAmount] = useState('');
45	  const [error, setError] = useState('');
46	
47	  const create = useMutation({
48	    mutationFn: () =>
49	      postJson<Invoice>('/api/invoices', { projectId, amount: Number(amount) }),
50	    onSuccess: () => {
51	      setAmount('');
52	      void queryClient.invalidateQueries({ queryKey: ['invoices'] });
53	    },
